1	/**
2	 * workflow-runs.ts — find the run a dispatch started, and wait for it to finish.
3	 *
4	 * `dispatchWorkflow` says GitHub accepted a `workflow_dispatch`. That is not the
5	 * same as the deployment having happened: it is a receipt for the request. A
6	 * deployment that creates a release tag dispatches the tag's own deployment and,
7	 * before this module existed, returned success the moment the request was
8	 * accepted. The merge-side run went green while the release it was supposed to
9	 * produce did not exist yet, and the next step in the chain failed looking for it.
10	 *
11	 * ## Which run is the one that was just asked for
12	 *
13	 * `gh workflow run` prints the run URL when it can, but not reliably and not as
14	 * machine-readable output. So the run is found by asking for the newest
15	 * `workflow_dispatch` run of that workflow on that ref. A tag is immutable and is
16	 * dispatched once, so for the tag bridge there is no older run for the same ref to
17	 * confuse it with. The ref is also what `gh run list --branch` matches for a tag:
18	 * GitHub reports a tag run's `headBranch` as the tag name.
19	 *
20	 * ## Why polling rather than `gh run watch`
21	 *
22	 * `gh run watch` refuses to authenticate with a fine-grained PAT, because it wants
23	 * `checks: read` and no such fine-grained permission exists. The job that dispatches
24	 * holds an Actions token, which would work, but the helper stays a plain poll so a
25	 * different caller is not tied to that. It also makes the two questions separate:
26	 * "did the run appear" and "how did it end".
27	 */
28	import { gh, ghRead } from "./gh.ts";
29	
30	/** A workflow run, as much of it as the wait needs. */
31	export interface WorkflowRun {
32	  readonly id: number;
33	  readonly status: string;
34	  readonly conclusion: string | null;
35	}
36	
37	/** How long a wait may last, and how often it asks. */
38	export interface RunWaitOptions {
39	  /** Number of reads, one after the first. */
40	  readonly attempts: number;
41	  /** Milliseconds between reads. */
42	  readonly intervalMs: number;
43	}
44	
45	/**
46	 * Test seam and operational bound, in the same shape as `ATOMATON_FAKE_GH`.
47	 *
48	 * The default is calibrated against a release publish: the tag deployment has a
49	 * sixty-minute job timeout, and the merge-side run holds its runner while it waits.
50	 * A test sets both to one attempt and no interval, so it exercises the answer
51	 * rather than the clock.
52	 */
53	export const RUN_WAIT_ATTEMPTS_VAR = "ATOMATON_RUN_WAIT_ATTEMPTS";
54	export const RUN_WAIT_INTERVAL_MS_VAR = "ATOMATON_RUN_WAIT_INTERVAL_MS";
55	
56	const DEFAULT_ATTEMPTS = 420;
57	const DEFAULT_INTERVAL_MS = 10_000;
58	
59	/**
60	 * A positive whole number from the environment, or the fallback.
61	 *
62	 * The interval used to accept `0`, and `Number("")` is `0`: an unset variable was
63	 * read as "poll with no sleep", spent the 420-poll bound in minutes, and reported a
64	 * deploy that was still building as unreadable. Neither setting has a useful zero,
65	 * so absent, zero and nonsense all fall back.
66	 */
67	function positiveInt(raw: string | undefined, fallback: number): number {
68	  const value = Number((raw ?? "").trim());
69	  return Number.isInteger(value) && value > 0 ? value : fallback;
70	}
71	
72	/** The wait bounds this process was configured with. */
73	export function runWaitOptions(env: NodeJS.ProcessEnv = process.env): RunWaitOptions {
74	  return {
75	    attempts: positiveInt(env[RUN_WAIT_ATTEMPTS_VAR], DEFAULT_ATTEMPTS),
76	    intervalMs: positiveInt(env[RUN_WAIT_INTERVAL_MS_VAR], DEFAULT_INTERVAL_MS),
77	  };
78	}
79	
80	function parseRun(raw: unknown): WorkflowRun | null {
81	  if (typeof raw !== "object" || raw === null) return null;
82	  const record = raw as Record<string, unknown>;
83	  if (typeof record.databaseId !== "number" || typeof record.status !== "string") return null;
84	  return {
85	    id: record.databaseId,
86	    status: record.status,
87	    conclusion: typeof record.conclusion === "string" ? record.conclusion : null,
88	  };
89	}
90	
91	/**
92	 * The newest `workflow_dispatch` run of `workflow` on `ref`, or null when there is
93	 * none yet.
94	 *
95	 * Null rather than throwing for the same reason `readTagNames` returns null: "no run
96	 * yet" and "the question could not be asked" are both non-answers, and the caller
97	 * retries either.
98	 */
99	export function newestDispatchRun(repo: string, workflow: string, ref: string): WorkflowRun | null {
100	  const { code, stdout } = ghRead(
101	    "run",
102	    "list",
103	    "--repo",
104	    repo,
105	    "--workflow",
106	    workflow,
107	    "--branch",
108	    ref,
109	    "--event",
110	    "workflow_dispatch",
111	    "--limit",
112	    "1",
113	    "--json",
114	    "databaseId,status,conclusion",
115	  );
116	  if (code !== 0) return null;
117	  try {
118	    const runs = JSON.parse(stdout || "[]") as unknown;
119	    if (!Array.isArray(runs)) return null;
120	    return parseRun(runs[0]);
121	  } catch {
122	    return null;
123	  }
124	}
125	
126	/** Wait for the run a dispatch started to appear. */
127	export function waitForDispatchRun(
128	  repo: string,
129	  workflow: string,
130	  ref: string,
131	  options: RunWaitOptions = runWaitOptions(),
132	): WorkflowRun | null {
133	  for (let attempt = 0; attempt < options.attempts; attempt += 1) {
134	    const run = newestDispatchRun(repo, workflow, ref);
135	    if (run) return run;
136	    if (attempt + 1 < options.attempts) Bun.sleepSync(options.intervalMs);
137	  }
138	  return null;
139	}
140	
141	/**
142	 * What a bounded wait saw.
143	 *
144	 * `finished` is the run once it completed. `null` means the bound was spent first,
145	 * and the other two fields are then the failure's evidence: how many reads were
146	 * made, and what the last one said. A wait that gives up and reports only "could
147	 * not be read" leaves the person who has to recover from it nothing to act on.
148	 */
149	export interface RunWaitOutcome {
150	  readonly finished: WorkflowRun | null;
151	  readonly polls: number;
152	  readonly last: WorkflowRun | null;
153	}
154	
155	/**
156	 * Wait for `runId` to finish, and say how it ended and, when it did not, what was
157	 * seen instead.
158	 *
159	 * A run that has completed is returned even when its conclusion is not `success`;
160	 * deciding what a failure means belongs to the caller, and the dispatch script is
161	 * the one that fails its job over it.
162	 */
163	export function waitForRunCompletion(
164	  repo: string,
165	  runId: number,
166	  options: RunWaitOptions = runWaitOptions(),
167	): RunWaitOutcome {
168	  let last: WorkflowRun | null = null;
169	  let polls = 0;
170	  for (let attempt = 0; attempt < options.attempts; attempt += 1) {
171	    polls += 1;
172	    const { code, stdout } = ghRead(
173	      "run",
174	      "view",
175	      String(runId),
176	      "--repo",
177	      repo,
178	      "--json",
179	      "databaseId,status,conclusion",
180	    );
181	    if (code === 0) {
182	      try {
183	        const run = parseRun(JSON.parse(stdout || "{}") as unknown);
184	        if (run) {
185	          last = run;
186	          if (run.status === "completed") return { finished: run, polls, last };
187	        }
188	      } catch {
189	        // A malformed answer is not the run having finished; ask again.
190	      }
191	    }
192	    if (attempt + 1 < options.attempts) Bun.sleepSync(options.intervalMs);
193	  }
194	  return { finished: null, polls, last };
195	}

